  /** HTTP 400. The paging cursor is malformed, was not signed by this deployment, or is for another topic. */
  CursorInvalid: "KUI-CURSOR-INVALID",
  /** HTTP 400. The paging cursor exceeds the size limit; narrow the request to fewer partitions. */
  CursorTooLarge: "KUI-CURSOR-TOO-LARGE",
  /** HTTP 400. The smart filter expression could not be compiled. */
  FilterCompile: "KUI-FILTER-COMPILE",
