/** Every known reason, for tests and for exhaustiveness checks over the vocabulary. */
export const AllReasonCodes: readonly KnownReasonCode[] = Object.values(ReasonCodes);

/**
 * The event names every KUI stream uses (ADR-035).
 *
 * `error` is terminal and carries an error envelope, `done` is terminal and carries the continuation
 * cursor on its `id:`, `heartbeat` exists only to stop a proxy from reaping an idle connection, and
 * `phase` reports progress. A stream may add data events of its own; these four are shared by all of
 * them, which is why a caller lists only its own and never these.
 */
export const SseEventNames = {
  Phase: "phase",
  Done: "done",
  Error: "error",
  Heartbeat: "heartbeat",
  Capabilities: "capabilities",
} as const;

/** The names every stream shares, which a caller must not list among its own data events. */
export const SharedSseEventNames: readonly string[] = [
  "phase",
  "done",
  "error",
  "heartbeat",
];

